<script setup lang="ts">
import {onMounted,onUnmounted,ref,watch} from 'vue';import type {RequestFn} from './media';import {date,states} from './lib';
const props=defineProps<{request:RequestFn,kind:'jobs'|'audit'}>();const rows=ref<Record<string,any>[]>([]),retention=ref<Record<string,any>>({}),busy=ref(false),error=ref(''),notice=ref(''),confirming=ref(false),confirmed=ref(false);let timer:ReturnType<typeof setInterval>;
async function load(){const kind=props.kind,[data,policy]=await Promise.all([props.request('admin/'+kind),props.request('admin/record-retention?kind='+kind)]);if(kind!==props.kind)return;rows.value=data;retention.value=policy}
async function act(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
async function clear(){if(!confirmed.value)return;await act(async()=>{await props.request('admin/record-retention?kind='+props.kind,'POST',{confirmed:true});confirming.value=false;confirmed.value=false;notice.value='历史记录已清理，业务与付款数据保留';await load()})}
watch(()=>props.kind,()=>{rows.value=[];confirming.value=false;confirmed.value=false;notice.value='';void act(load)});onMounted(()=>{void act(load);timer=setInterval(()=>{if(document.visibilityState==='visible'&&!busy.value&&!confirming.value)void act(load)},30000)});onUnmounted(()=>clearInterval(timer));
</script>
<template><div v-if="error" class="alert error" role="alert">{{error}}</div><div v-if="notice" class="alert" role="status">{{notice}}</div><section class="panel"><div class="section-head"><div><h3>{{kind==='jobs'?'后台任务':'操作记录'}}保留策略</h3><p class="muted" v-if="kind==='audit'">自动保留最近 {{retention.audit_days||30}} 天，最多 {{retention.audit_limit||10000}} 条；此页展示最近 300 条。</p><p class="muted" v-else>已完成 / 已回滚任务自动保留最近 {{retention.completed_job_days||30}} 天，最多 {{retention.completed_job_limit||2000}} 条；此页展示最近 200 条。</p></div><button v-if="retention.can_clear" :disabled="busy" @click="confirming=true;confirmed=false">{{kind==='audit'?'清空操作记录':'清理已完成任务'}}</button></div><p class="muted">{{kind==='audit'?'当前操作记录 '+(retention.audit_count??'—')+' 条。':'已完成记录 '+(retention.completed_jobs??'—')+' 条；排队、处理中及失败待重试任务 '+(retention.protected_jobs??'—')+' 条。'}} 自动清理每 5 分钟检查一次。订单、付款与开通凭据保留。</p></section>
<section class="panel task-board" :aria-label="kind==='jobs'?'后台任务列表':'操作记录列表'"><article v-for="r in rows" :key="r.id" class="task-record"><div class="task-title"><strong>{{r.kind||r.action}}</strong><span class="badge" :class="r.state">{{states[r.state]||r.actor}}</span></div><div class="task-object"><small>对象</small><code>{{r.subject||'—'}}</code></div><div class="task-result"><details v-if="r.detail"><summary>查看结果详情</summary><pre>{{r.detail}}</pre></details><small>{{date(r.updated_at||r.created_at)}}</small></div><button v-if="r.state==='failed'&&['fulfill','mail','access','migrate','policy'].includes(r.kind)" :disabled="busy" @click="act(async()=>{await request('admin/jobs','POST',{id:r.id});await load()})">重试</button></article><div v-if="!rows.length" class="empty">暂无记录</div></section>
<div v-if="confirming" class="modal-backdrop" @click.self="!busy&&(confirming=false)"><form class="modal" role="dialog" aria-modal="true" aria-label="确认清理历史记录" @submit.prevent="clear"><h2>确认清理{{kind==='audit'?'操作记录':'已完成任务'}}</h2><p>{{kind==='audit'?'当前操作记录将清空，保留本次清理的审计标记。':'仅清理已完成和已回滚任务；待处理及失败任务保留。'}}此操作不可撤销。</p><label class="multi"><input type="checkbox" v-model="confirmed">我确认清理历史记录，订单和付款记录保持保留</label><div class="modal-actions"><button type="button" :disabled="busy" @click="confirming=false">取消</button><button class="primary" :disabled="busy||!confirmed">确认清理</button></div></form></div></template>

<style scoped>.task-board{padding:0;overflow:hidden}.task-record{display:grid;grid-template-columns:minmax(130px,.8fr) minmax(140px,1fr) minmax(180px,1.5fr) auto;align-items:center;gap:20px;padding:18px 20px;border-bottom:1px solid var(--border);font-size:12px}.task-record:last-child{border-bottom:0}.task-record>div{min-width:0;overflow-wrap:anywhere}.task-title{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.task-record .badge{white-space:normal}.task-object small,.task-result>small{display:block;font-size:10px;line-height:1.7}.task-object code{font-size:11px}.task-result summary{cursor:pointer;color:var(--accent);margin-bottom:5px}.task-result pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:11px;max-height:240px;overflow-y:auto;line-height:1.7;background:var(--surface-soft);padding:12px;border-radius:8px}.task-record button{min-height:38px;font-size:12px}@media(max-width:1000px){.task-record{grid-template-columns:minmax(100px,1fr) minmax(120px,1fr);gap:12px}.task-result{grid-column:1/-1}.task-record>button{justify-self:start}}@media(max-width:760px){.task-board{padding:0!important}.task-record{padding:17px;grid-template-columns:minmax(0,1fr)}.task-title,.task-object,.task-result{grid-column:1/-1}.task-title{justify-content:space-between}.task-object code{display:block}.task-record>button{min-width:85px}}</style>
